class Stack {
  constructor() {
    this.items = [];
  }

  push(value) {
    this.items.push(value);
  }

  pop() {
    return this.items.pop();
  }

  peek() {
    return this.items[this.items.length - 1];
  }

  isEmpty() {
    return this.items.length === 0;
  }
}

const browserHistory = new Stack();
browserHistory.push('home');
browserHistory.push('products');
browserHistory.push('item-42');
console.log(browserHistory.pop());    // 'item-42'
console.log(browserHistory.peek());   // 'products'

class Queue {
  constructor() {
    this.items = [];
  }

  enqueue(value) {
    this.items.push(value);
  }

  dequeue() {
    return this.items.shift();
  }

  peek() {
    return this.items[0];
  }

  isEmpty() {
    return this.items.length === 0;
  }
}

const printQueue = new Queue();
printQueue.enqueue('doc-a');
printQueue.enqueue('doc-b');
printQueue.enqueue('doc-c');
console.log(printQueue.dequeue()); // 'doc-a'
console.log(printQueue.peek());    // 'doc-b'
